import pandas as pd
from fastmcp import FastMCP
from pydantic import Field

# Intializing the FastMCP Server
mcp = FastMCP("Insurance Claims Agent Tools")

# Path to the DB generated by Faker
DATA_PATH = "data/policies.csv"

@mcp.tool()
def verify_policy(policy_id: str = Field(description="The uniqueUK insurance policy identifier, e.g., POL-UK-0001")) -> dict:
    """Verifies if an insurance policy exists in the UK database, checks its active status, and retrieves deductible details."""
    try:
        if not pd.io.common.file_exists(DATA_PATH):
            return {"status": "Error", "message": "Policy database not found. You can run generate_data.py to generate it first."}

        df = pd.read_csv(DATA_PATH)
        policy = df[df["policy_id"] == policy_id.strip()]

        if policy.empty:
            return{"status": "Error", "message": f"Policy ID '{policy_id}' not found in the UK Database."}

        row = policy.iloc[0]

        return{
            "status": "Success",
            "policy_id": row["policy_id"],
            "client_name": row["client_name"],
            "coverage_type": row["coverage_type"],
            "deductible": float(row["deductible"]),
            "policy_status": row["status"]
        }
    except Exception as e:
        return {"status": "Error", "message": str(e)}


@mcp.tool()
def calculate_payout(
    policy_id: str = Field(description="The policy ID associated with the claim, e.g., POL-UK-0001"), 
    claim_amount: float = Field(description="The monetary claim amount in pounds (£)")
) -> dict:
    """Calculates the net insurance payout by looking up the policy deductible and subtracting it from the claim amount."""

    # Verify the policy using the verify_policy tool logic
    policy_info = verify_policy(policy_id)
    if policy_info["status"] != "Success":
        return policy_info

    # Check if the policy is still Active
    if policy_info["policy_status"] != "Active":
        return{
            "status": "Rejected",
            "policy_id": policy_id,
            "client_name": policy_info["client_name"],
            "reason": "Policy is expired or inactive. Payout denied."
        }

    deductible = policy_info["deductible"]

    # Handle claims that are <= the deductible (excess)
    if claim_amount <= deductible:
        return{
            "status": "Approved with £0 Payout",
            "policy_id": policy_id,
            "client_name": policy_info["client_name"],
            "claim_amount": claim_amount,
            "deductible": deductible,
            "final_payout": 0.0,
            "note": "Claim amount is less than or equal to the policy deductible (excess). No payout issued."
        }

    # Calculate the net payout
    final_payout = round(claim_amount - deductible, 2)
    return{
        "status": "Approved",
        "policy_id": policy_id,
        "client_name": policy_info["client_name"],
        "claim_amount": claim_amount,
        "deductible": deductible,
        "final_payout": final_payout,
        "note": "Claim approved. Deductible successfully subtracted."
    }




if __name__ == "__main__":
    mcp.run()